setters:
private void closeChannel() {
    if (channel != null) {
        try {
            channel.close();
        } catch (IOException x) {
            // close didn't succeed
        }
    }
}

private void forceAndClose() throws IOException {
    if (channel != null) {
        try {
            channel.force(true);
        } finally {
            closeChannel();
        }
    }
}

@Override
public void handle(HttpServerExchange exchange, byte[] bytes) {
    context.body = Body.of(context, bytes);
    route.execute(context);
}

@Override
public void handle(HttpServerExchange exchange, byte[] chunk, boolean last) {
    try {
        if (chunk.length > 0) {
            chunkSize += chunk.length;
            if (chunkSize > maxRequestSize) {
                try {
                    context.sendError(new StatusCodeException(StatusCode.REQUEST_ENTITY_TOO_LARGE));
                } finally {
                    closeChannel();
                    channel = null;
                }
                return;
            }
            if (chunkSize <= bufferSize) {
                if (chunks == null) {
                    chunks = new ArrayList<>();
                }
                chunks.add(chunk);
            } else {
                // overflow
                if (file == null) {
                    file = context.getRouter().getTmpdir().resolve(("undertow" + System.nanoTime()) + "body");
                    channel = FileChannel.open(file, CREATE, WRITE);
                }
                if (chunks != null) {
                    List source = chunks;
                    chunks = null;
                    for (Object s : source) {
                        byte[] bytes = ((byte[]) (s));
                        channel.write(ByteBuffer.wrap(bytes), position);
                        position += bytes.length;
                    }
                    source.clear();
                }
                channel.write(ByteBuffer.wrap(chunk), position);
                position += chunk.length;
            }
        }
        if (last) {
            if (channel != null) {
                exchange.addExchangeCompleteListener(this);
                forceAndClose();
                channel = null;
