@Override
public void handle(HttpServerExchange exchange, byte[] chunk, boolean last) {
    try {
        if (chunk.length > 0) {
            chunkSize += chunk.length;
            if (chunkSize > maxRequestSize) {
                try {
                    context.sendError(new StatusCodeException(StatusCode.REQUEST_ENTITY_TOO_LARGE));
                } finally {
                    closeChannel();
                    channel = null;
                }
                return;
            }
            if (chunkSize <= bufferSize) {
                if (chunks == null) {
                    chunks = new ArrayList<>();
                }
                chunks.add(chunk);
            } else {
                // overflow
                if (file == null) {
                    file = context.getRouter().getTmpdir().resolve(("undertow" + System.nanoTime()) + "body");
                    channel = FileChannel.open(file, CREATE, WRITE);
                }
                if (chunks != null) {
                    List source = chunks;
                    chunks = null;
                    for (Object s : source) {
                        byte[] bytes = ((byte[]) (s));
                        channel.write(ByteBuffer.wrap(bytes), position);
                        position += bytes.length;
                    }
                    source.clear();
                }
                channel.write(ByteBuffer.wrap(chunk), position);
                position += chunk.length;
            }
        }
        if (last) {
            if (channel != null) // PATH: Test should invoke the next HttpServerExchange.addExchangeCompleteListener(...) [step in execution path]
            {
                exchange.addExchangeCompleteListener(this);
                forceAndClose();
                channel = null;
                context.body = Body.of(context, file);
            } else {
                context.body = Body.of(context, bytes(((int) (chunkSize))));
            }
            route.execute(context);
        }
    } catch (IOException x) {
        try {
            context.sendError(x);
        } finally {
            closeChannel();
            channel = null;
            exchange.endExchange();
        }
    }
}

